import java.util.*;

class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        Arrays.sort(initial);
        int best = initial[0];
        int bestInfected = Integer.MAX_VALUE;
        for (int removed : initial) {
            int infected = simulate(graph, initial, removed);
            if (infected < bestInfected) {
                bestInfected = infected;
                best = removed;
            }
        }
        return best;
    }

    private int simulate(int[][] graph, int[] initial, int removed) {
        int n = graph.length;
        boolean[] seen = new boolean[n];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int node : initial) {
            if (node != removed) {
                seen[node] = true;
                queue.offer(node);
            }
        }
        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int next = 0; next < n; next++) {
                if (next != removed && graph[node][next] == 1 && !seen[next]) {
                    seen[next] = true;
                    queue.offer(next);
                }
            }
        }
        int count = 0;
        for (boolean infected : seen) {
            if (infected) {
                count++;
            }
        }
        return count;
    }
}

