class Solution {
    private int[][] graph;
    private boolean[] seen;
    private int removed;

    public int minMalwareSpread(int[][] graph, int[] initial) {
        this.graph = graph;
        Arrays.sort(initial);
        int best = initial[0];
        int bestCount = Integer.MAX_VALUE;
        for (int candidate : initial) {
            removed = candidate;
            seen = new boolean[graph.length];
            for (int source : initial) {
                if (source != removed && !seen[source]) {
                    dfs(source);
                }
            }
            int count = 0;
            for (boolean infected : seen) {
                if (infected) {
                    count++;
                }
            }
            if (count < bestCount) {
                bestCount = count;
                best = candidate;
            }
        }
        return best;
    }

    private void dfs(int node) {
        if (node == removed || seen[node]) {
            return;
        }
        seen[node] = true;
        for (int next = 0; next < graph.length; next++) {
            if (graph[node][next] == 1) {
                dfs(next);
            }
        }
    }
}

