class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        Arrays.sort(initial);
        int n = graph.length;
        int best = initial[0];
        int bestCount = Integer.MAX_VALUE;
        for (int removed : initial) {
            DSU dsu = new DSU(n);
            for (int i = 0; i < n; i++) {
                if (i == removed) {
                    continue;
                }
                for (int j = i + 1; j < n; j++) {
                    if (j != removed && graph[i][j] == 1) {
                        dsu.union(i, j);
                    }
                }
            }
            boolean[] infectedRoot = new boolean[n];
            for (int node : initial) {
                if (node != removed) {
                    infectedRoot[dsu.find(node)] = true;
                }
            }
            int count = 0;
            for (int node = 0; node < n; node++) {
                if (node != removed && infectedRoot[dsu.find(node)]) {
                    count++;
                }
            }
            if (count < bestCount) {
                bestCount = count;
                best = removed;
            }
        }
        return best;
    }

    static class DSU {
        int[] parent;
        int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) {
                return;
            }
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }
    }
}

