class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        Arrays.sort(initial);
        boolean[] infected = new boolean[n];
        for (int node : initial) {
            infected[node] = true;
        }

        int[] component = new int[n];
        Arrays.fill(component, -1);
        List<Integer> sizes = new ArrayList<>();
        for (int node = 0; node < n; node++) {
            if (!infected[node] && component[node] == -1) {
                sizes.add(labelComponent(graph, infected, component, node, sizes.size()));
            }
        }

        int[] owner = new int[sizes.size()];
        Arrays.fill(owner, -1);
        for (int source : initial) {
            Set<Integer> touched = new HashSet<>();
            for (int node = 0; node < n; node++) {
                if (graph[source][node] == 1 && component[node] >= 0) {
                    touched.add(component[node]);
                }
            }
            for (int comp : touched) {
                if (owner[comp] == -1) {
                    owner[comp] = source;
                } else if (owner[comp] != source) {
                    owner[comp] = -2;
                }
            }
        }

        int[] saved = new int[n];
        for (int comp = 0; comp < owner.length; comp++) {
            if (owner[comp] >= 0) {
                saved[owner[comp]] += sizes.get(comp);
            }
        }

        int best = initial[0];
        for (int node : initial) {
            if (saved[node] > saved[best]) {
                best = node;
            }
        }
        return best;
    }

    private int labelComponent(int[][] graph, boolean[] infected, int[] component, int start, int id) {
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.offer(start);
        component[start] = id;
        int size = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            size++;
            for (int next = 0; next < graph.length; next++) {
                if (!infected[next] && graph[node][next] == 1 && component[next] == -1) {
                    component[next] = id;
                    queue.offer(next);
                }
            }
        }
        return size;
    }
}

